sp_widget.client_script:
api.controller = function($scope, $location, spUtil, spModal, $httpParamSerializer, $rootScope, $timeout) {
    /* widget controller */
    var c = this;
    c.data = $scope.data;

    $scope.$on('showDetailDate', function(event, data) {
        c.data.detail = data;
        c.data.refreshDate = true;
        c.server.update().then(function() {
            c.data.refreshDate = false;
        });
    });

    $scope.getMembership = function() {
       c.data.groupID = '';
       c.data = $scope.data;
       c.data.showMember = true;
			 c.data.groupID = toString($scope.data.member);
			 c.server.update().then(function() {
         c.data.groupID = String(c.data.member);
				 c.data.showMember = false;
        });
    };

    if ((c.data.secAcc != null || c.data.secCode != null) && !c.data.errSummary && c.data.outboundID != null) {
        //document.getElementsByClassName('position-summary')[0].style.display = 'block';
		//MSSOTIQUBE-890 Avoid DOM manipulation
		$(".position-summary").show();

        if (c.data.detail != null) {
            //document.getElementsByClassName('position-details')[0].style.display = 'block';
			//MSSOTIQUBE-890 Avoid DOM manipulation
			$(".position-details").show();
        }
    }

    $scope.isFieldBlurred = false;
    $scope.checkFormat = function() {
        $scope.isFieldBlurred = true;
    };

    $scope.getHoldingsData = function() {
        c.data = $scope.data;
		    var grp = String(c.data.member);
        //document.getElementsByClassName('position-summary')[0].style.display = 'none';
        //document.getElementsByClassName('position-details')[0].style.display = 'none';
		    //MSSOTIQUBE-890 Avoid DOM manipulation
		    $(".position-summary").hide();
		    $(".position-details").hide();
        if ((c.data.owningBusiness === '' || c.data.owningBusiness === null) && (c.data.groupID === null || c.data.groupID === '')) {
            alert("Owning Business and Group Membership are mandatory, please select a value");
        } else if (c.data.owningBusiness === null || c.data.owningBusiness === '') {
            alert("Owning Business is mandatory, please select a value");
        } else if (c.data.groupID === null || c.data.groupID === '') {
            alert("Group Membership is mandatory, please select a value");
        } else if (c.data.owningBusiness !== null && c.data.groupID !== null && (c.data.secAcc === '' || c.data.secAcc === null) && (c.data.secCode === '' || c.data.secCode === null)) {
            alert("Please enter at least one of Securities Account or Security Code");
        } else if (c.data.secAcc !== null && c.data.secAcc !== '' && !(/^\d{12}$|^\d{3}-\d{6}-\d{3}$|^[0-9]{1,13}$/.test(c.data.secAcc))) {
            alert("Input Securities Account format or length is invalid. Please enter valid Securities Account");
        } else if (c.data.owningBusiness != null && c.data.groupID != null && c.data.owningBusiness != '' && c.data.groupID != '' && c.data.disablebutton == false) {
            $location.search({
                id: 'security_holdings_enquiry',
                owningBusiness: c.data.owningBusiness,
                groupID: grp,
                secAcc: c.data.secAcc,
                secCodeChk: c.data.secCodeChk,
                secCode: c.data.secCode,
                spa: 1,
                userid: c.data.userID
            });
            c.data.disablebutton = true;
            c.server.update().then(function() {
                var params = $location.search();
                angular.extend(params, {
                    outid: c.data.outboundID,
                    iferr: c.data.errSummary,
                    date: c.data.date,
                });
                $location.search($httpParamSerializer(params));
                if (c.data.attsync == true) {
                    // Handle attachment sync
                } else if ((!c.data.errSummary)) {
                    $timeout(function() {
                        $rootScope.$broadcast('showPositionSummary', '');
                    }, 500);
                } else {
                    if (c.data.err40x) {
                        var msg1 = 'Positions Data sync was not completed. Please check you have used the correct format: Country in Capitals, Group Id in Capitals, Account as XXX-XXXXXX-XXX/XXXXXXXXXXXX, Please also check you have access to the Market provided.';
                        spUtil.addErrorMessage(msg1);
                        //document.getElementsByClassName('position-summary')[0].style.display = 'none';
						//MSSOTIQUBE-890 Avoid DOM manipulation
						$(".position-summary").hide();
                    } else {
                        var msg = 'Position data sync was not completed due to technical error. Please check the messages manually. The technical issue has been reported to HSBC technical team.';
                        spUtil.addErrorMessage(msg);
                        //document.getElementsByClassName('position-summary')[0].style.display = 'none';
						//MSSOTIQUBE-890 Avoid DOM manipulation
						$(".position-details").hide();
                    }
                }
            });
        }
    };
};

sp_widget.css:
/*h3 {text-align:center; color: Green;}*/
h3{margin-top: 0;}

h4{color: red;}

h5{background-color: #c3ddf0; padding:5px}

table {width:100%; margin-bottom:20px; table-layout:auto}

.required::after{
  content:" *";
  color:red;
  font-size:15px;  
}
.required1::after{
  content:" **";
  color:red;
  font-size:15px;
}

.heading{
background-color: RGB(var(--now-color_background--secondary, var(--now-color--neutral-1, 246, 247, 247)));
color: RGB(var(--now-form-field--color, var(--now-color_text--primary, var(--now-color--neutral-18, 22, 27, 28))));

}


.sn-canvas-header-tools {
    position: relative;
    min-height: 48px;
    line-height: 48px;
    background-color: RGB(var(--now-color--neutral-2,240,241,245));
    border-bottom: 1px solid #bdc0c4;
    border-bottom-width: 1px;
    border-bottom-style: solid;
    border-bottom-color: rgb(189, 192, 196);
    box-shadow: rgba(0, 0, 0, 0.08) 0 1px 2px;
    padding: 0px;
    direction: ltr;
    display: flex;
    flex-flow: row wrap;
    justify-content: space-between;
    flex: 1 0 auto;
    vertical-align: sub;
  font-family: Lato, Arial, sans-serif;
      font-size: 18px;
  color:#151920;

}

.field-container {
  position: relative;
  white-space: nowrap;
}


.error-message {
  position: absolute;
  top: calc(100% + 5px);
  left: 0;
  color: red;
  font-size: 14px;
 	display: none;
  z-index: 1;
}

input.ng-invalid.ng-dirty + .error-message {
  display: block;
}




.notification {
    //margin: 10px 10px auto;
    width: calc(100% - 0px);
    display: table;
    padding: 0px 0px 0px 0px;
    word-break: break-word;
    hyphens: auto;
    border: 1px solid transparent;
    border-radius: 4px;
    font-size: var(--now-global-font-size--md, 14px);
    //margin-block-start: var(--now-global-space--xs,4px);
    min-height: calc(22px + 8px); 
    position: relative;
    background-color: RGB(var(--now-alert--info--background-color,var(--now-color_alert--info-0,195,221,240)));
    border-color: RGB(var(--now-alert--info--border-color,var(--now-color_alert--info-1,104,171,218)));
    font-family: Lato, Arial, sans-serif;
    font-size: 14px;
  color:#151920;
}

.button{
margin: 0;
 margin-inline-start: var(--now-global-space--xs,4px);
  background: #4F52BD;
    border-color: RGB(var(--now-button--primary--border-color,var(--now-color--primary-3,15,67,55)));
    color: RGB(var(--now-button--primary--color,var(--now-color_text--primary-actionable,var(--now-color--neutral-0,255,255,255))));
      align-items: center;
    border-radius: 4px;
    border: none;
    box-shadow: none;
    cursor: pointer;
    display: inline-flex;
    font-size: var(--now-global-font-size--md, 14px);
    font-weight: 700;
    height: 32px;
    justify-content: center;
    line-height: 1;
    padding: 0 var(--now-global-space--md,10px);
    text-decoration: none;
    transition: background-color .3s cubic-bezier(.075, .82, .165, 1),border-color .3s cubic-bezier(.075, .82, .165, 1),box-shadow .3s cubic-bezier(.075, .82, .165, 1),color .3s cubic-bezier(.075, .82, .165, 1),opacity .3s cubic-bezier(.075, .82, .165, 1),transform .1s cubic-bezier(.77, 0, .175, 1);
    user-select: none;
    white-space: nowrap;
}

sp_widget.script:
(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */
    if (input) {
        if (input.refreshDate) {
            data.detail = $sp.getParameter('detail');
            return;
        }

        if (input.showMember) {

            data.member = [];
            var query = 'siteIN' + input.owningBusiness;
            var group = new GlideRecord('x_hsb11_mss_c_proc_custody_group_member_to_site');
            group.addEncodedQuery(query);
            group.query();
            while (group.next()) {
                data.member.push(group.getDisplayValue('group_member'));
            }

            return;

        }
    }
    data.hidebutton = false;
    data.attsync = false;
    data.errSummary = false;
    data.err40x = false;
    data.res = false;
    //data.country = 'HK';
    data.groupID = $sp.getParameter('groupID');
    data.secAcc = $sp.getParameter('secAcc');
    data.secCodeChk = $sp.getParameter('secCodeChk');
    data.secCode = $sp.getParameter('secCode');
    data.outboundID = $sp.getParameter('outid');
    data.date = $sp.getParameter('date');
    data.detail = $sp.getParameter('detail');
    data.userID = gs.getUserID();
    data.disablebutton = false;
    data.owningBusiness = $sp.getParameter('owningBusiness');



    var userGr = new GlideRecord('sys_user');
    userGr.addQuery('sys_id', gs.getUserID());
    userGr.query();
    if (userGr.next()) {
        var associatedMarket = userGr.getDisplayValue('u_associated_business_markets');
        if (associatedMarket !== null) {
            data.market = associatedMarket.split(',');
        }
    }


    if (gs.getProperty('x_hsb11_mss_pos.hsbcmss_el_custodyPositiononDemand_active') == 'false')
        data.hidebutton = true;
    if (data.secCodeChk == undefined || data.secCodeChk == null)
        data.secCodeChk = 'hsbcIdentifiers';
    if (input) {
        data.disablebutton = true;
        var owningBusiness = input.owningBusiness;
        var grpId = input.groupID;
        var secAcc = input.secAcc;
        var secCodeChk = input.secCodeChk;
        if (input.secCode != null) {
            var secCode = input.secCode.toUpperCase();
        } else {
            var secCode = input.secCode;
        }

        var recordExists = new x_hsb11_mss_pos.HSBCCustodySPUtils().checkRecordExists();
        if (recordExists) {
            gs.addErrorMessage('Submission is in progress. Please wait.');
            data.attsync = true;
        } else {
            var createOutboundRecord = new x_hsb11_mss_pos.HSBCCustodySPUtils().createOutboundRecord(owningBusiness, grpId, secAcc, secCode, secCodeChk);
            data.outboundID = createOutboundRecord;
            data.date = new GlideDateTime().toString();
            waitforresponse(createOutboundRecord);
        }
    }

})();

function waitforresponse(id) {
    //MSSOTIQUBE-1921 --> reduced sleep time from 3000
    new global.SleepForScopedApp().sleep(1500);
    var chkResponse = new x_hsb11_mss_pos.HSBCCustodySPUtils().checkResponseSummary(id);
    if (chkResponse == false) {
        waitforresponse(id);
    } else if (chkResponse == '200') {
		// new global.SleepForScopedApp().sleep(1000); //MSSOTIQUBE-1921 --> removing this to reduce delay
        data.errSummary = false;
        data.disablebutton = false;
    } else if (chkResponse == 'error') {
        data.errSummary = true;
        data.disablebutton = false;
    } else if (chkResponse == '40xerror') {
        data.errSummary = true;
        data.disablebutton = false;
        data.err40x = true;
    }
}
